package com.backend.nutri_predic.consumo.service; import com.backend.nutri_predic.consumo.dto.SeguimientoPcsResponse; import com.backend.nutri_predic.consumo.repository.*; import java.time.LocalDate; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class SeguimientoPcsService {private final EvaluacionConsumoRepository evaluaciones;private final DetalleEvaluacionConsumoRepository detalles;public SeguimientoPcsService(EvaluacionConsumoRepository e,DetalleEvaluacionConsumoRepository d){evaluaciones=e;detalles=d;}@Transactional(readOnly=true)public SeguimientoPcsResponse evolucion(Long clienteId,LocalDate hasta){var porFecha=new TreeMap<LocalDate,com.backend.nutri_predic.consumo.entity.EvaluacionConsumo>();for(var e:evaluaciones.findByClienteIdOrderByFechaEvaluacionDesc(clienteId))if(!e.getFechaCorte().isAfter(hasta))porFecha.putIfAbsent(e.getFechaCorte(),e);var dias=porFecha.values().stream().map(e->new SeguimientoPcsResponse.DiaPcs(e.getFechaCorte(),e.getEstadoClasificacion().name(),detalles.findByEvaluacionIdOrderByIdAsc(e.getId()).stream().filter(d->"CUMPLE".equals(d.getResultado())).map(d->new SeguimientoPcsResponse.ExcesoPcs(d.getComponente(),d.getFuente())).filter(d->d.componente()!=null).distinct().toList())).toList();var actuales=dias.stream().filter(d->!d.fecha().isBefore(hasta.minusDays(6))).toList();var previos=dias.stream().filter(d->!d.fecha().isBefore(hasta.minusDays(13))&&d.fecha().isBefore(hasta.minusDays(6))).toList();var actual=contar(actuales);var anterior=contar(previos);String tendencia=actuales.size()<7||previos.size()<7?"NO_CALCULABLE":actual.diasAlto()>anterior.diasAlto()?"EMPEORA":actual.diasAlto()<anterior.diasAlto()?"MEJORA":"ESTABLE";return new SeguimientoPcsResponse(dias,actual.diasAlto(),actual.diasNoAlto(),actual.diasNoDeterminada(),anterior,tendencia);}private SeguimientoPcsResponse.ResumenVentanaPcs contar(java.util.List<SeguimientoPcsResponse.DiaPcs> dias){return new SeguimientoPcsResponse.ResumenVentanaPcs(dias.stream().filter(d->"ALTO".equals(d.resultado())).count(),dias.stream().filter(d->"NO_ALTO".equals(d.resultado())).count(),dias.stream().filter(d->"NO_DETERMINADA".equals(d.resultado())).count());}}
